import mongoose from 'mongoose';

const { Schema } = mongoose;

/**
 * One durable record per backup execution.
 *
 * WHY THIS EXISTS. The archive directory and the scheduler log answer "what
 * exists" and "what ran lately", but both are host state: the log rotates at
 * 2 MB and both are invisible to any API instance that is not the machine that
 * runs the scheduler. A failed or interrupted run therefore had no durable
 * record at all. This collection is that record.
 *
 * THE RUN ID IS THE IDENTITY. `runId` is generated by the runner process and is
 * unique, so a retried write updates its own row instead of appending a second
 * one. A row that is still `RUNNING` long after it started is INTERRUPTED: the
 * process died before it could finish, and the read path derives that state
 * rather than pretending the run succeeded.
 *
 * The row holds no credential, no passphrase and no private key — only the
 * archive's name, its published SHA-256 digest and the failure text the runner
 * already prints.
 */
/**
 * Who started the run, as the runtime reported it.
 *
 * Every field is nullable on purpose: a laptop has no run id, and a fabricated one would
 * turn "I do not know" into false evidence. The verdict on whether a SCHEDULED claim is
 * proved is derived at read time (`backupProvenance.service.ts`), not stored, so the rule
 * can be tightened without rewriting history.
 */
const provenanceSchema = new Schema(
  {
    source: { type: String, enum: ['github-actions', 'local'], default: null },
    event: { type: String, default: null },
    runId: { type: String, default: null },
    runAttempt: { type: Number, default: null },
    repository: { type: String, default: null },
    workflowRef: { type: String, default: null },
    ref: { type: String, default: null },
    sha: { type: String, default: null },
    actor: { type: String, default: null },
    runner: {
      name: { type: String, default: null },
      os: { type: String, default: null },
      arch: { type: String, default: null },
    },
    host: { type: String, default: null },
    platform: { type: String, default: null },
  },
  { _id: false },
);

const backupRunSchema = new Schema(
  {
    runId: { type: String, required: true, unique: true },
    trigger: {
      type: String,
      enum: ['SCHEDULED', 'MANUAL', 'CONSOLE', 'UNKNOWN'],
      default: 'SCHEDULED',
    },
    startedAt: { type: Date, required: true },
    finishedAt: { type: Date, default: null },
    outcome: {
      type: String,
      enum: ['RUNNING', 'SUCCESS', 'FAILED'],
      required: true,
    },
    archive: { type: String, default: null },
    sha256: { type: String, default: null },
    sizeBytes: { type: Number, default: null },
    offsite: {
      type: String,
      enum: ['verified', 'copied', 'present', 'missing', 'unknown'],
      default: 'unknown',
    },
    pruned: { type: [String], default: [] },
    archiveDir: { type: String, default: null },
    copyDir: { type: String, default: null },
    host: { type: String, default: null },
    provenance: { type: provenanceSchema, default: null },
    detail: { type: String, default: null },
    // One failure alert per run. `claimedAt` is set atomically before sending so
    // two deliveries cannot both mail the same failure; `sentAt` is the durable
    // "this run has been reported" mark and `error` keeps the last delivery
    // failure for an investigation without creating a second collection.
    alert: {
      kind: { type: String, enum: ['FAILED', 'INTERRUPTED'], default: null },
      claimedAt: { type: Date, default: null },
      sentAt: { type: Date, default: null },
      error: { type: String, default: null },
    },
  },
  { collection: 'backup_runs', timestamps: true, versionKey: false },
);

backupRunSchema.index({ startedAt: -1 });
backupRunSchema.index({ outcome: 1, startedAt: -1 });

const BackupRun = mongoose.model('BackupRun', backupRunSchema);

export default BackupRun;
